import math
import numpy as np
from collections.abc import Iterable
from xsum import xsum_add, xsum_round

# Method generated by OpenAI Astra 6.0 Max
def partition_by_time_helper(objects, times, k):
    """Return k groups of objects and their total times."""
    objects = list(objects)
    times = np.asarray(times, dtype=float)

    groups = [[] for _ in range(k)]
    totals = np.zeros(k)

    for rank, i in enumerate(np.argsort(times)[::-1]):
        # Seed each group once, ensuring nonempty groups.
        j = rank if rank < k else int(np.argmin(totals))
        groups[j].append(objects[i])
        totals[j] += times[i]

    return groups, totals

def safer_sum_helper(vals):
        vals = np.array(vals).flatten()
        vals_pos = np.sort(vals[vals >= 0])
        vals_neg = np.sort(vals[vals < 0])[::-1]
        return math.fsum(vals_pos) + math.fsum(vals_neg)

def compute_addmisibility_helper(lp, ext, point, axes, relative):
    lp_a = lp[axes]
    ext_a = ext[axes]
    left_dist =  np.abs(lp_a - point)
    right_dist = np.abs(point - (lp_a+ext_a))
    # Euclidean distance on specific axes
    dist = np.min(np.vstack([left_dist,right_dist]),axis=0)
    # If inside set to 0
    dist = dist * np.logical_or(point < lp_a, point > (lp_a+ext_a))
    if relative:
        return np.linalg.norm(dist/ext_a) >= np.sqrt(len(axes))
    else:
         return np.linalg.norm(dist) >= np.linalg.norm(ext_a)

def dyadic_partition_helper(lp, ext, axes, max_refinements):
    elements = [lp]
    next_ext = ext.copy()
    for axis in axes:
        if ext[axis]/2 < max_refinements[axis]:
            continue
        next_elements = []
        next_ext[axis] /= 2.0
        for el in elements:
            left = el
            right = el.copy()
            right[axis] += next_ext[axis]
            next_elements.append(left)
            next_elements.append(right)
        elements = next_elements
    return elements, next_ext

def safe_numeric_to_numpy(obj):
    def recursive_unpack(p):          
        if isinstance(p, Iterable):
            return [recursive_unpack(x) for x in p]
        else:
            return float(p)
    return np.array(recursive_unpack(obj),dtype=float)

def break_and_return_xsum_helper(accumulator):
    parts = []
    while True:
        value = xsum_round(accumulator)
        if value == 0.0:
            break
        parts.append(value)
        xsum_add(accumulator, -value)
    return parts